from pathlib import Path

controller_path = Path('src/app/linked-object-external-controller.ts')
controller = controller_path.read_text()

anchor = """export interface LinkedObjectRefreshCommitResultV1 {\n  readonly layer: LinkedObjectLayerV1;\n  readonly handlePersisted: boolean;\n}\n\n"""
insert = """export interface LinkedObjectRefreshCommitResultV1 {\n  readonly layer: LinkedObjectLayerV1;\n  readonly handlePersisted: boolean;\n}\n\nexport type LinkedObjectRefreshDecisionV1 = 'commit' | 'cancel';\n\nexport type LinkedObjectRefreshWorkflowStateV1 =\n  | Exclude<LinkedObjectRefreshStateV1, 'ready'>\n  | 'cancelled'\n  | 'stale'\n  | 'committed';\n\nexport type LinkedObjectReadyRefreshStageV1 = LinkedObjectRefreshStageV1 & {\n  readonly state: 'ready';\n  readonly handle: LinkedObjectExternalHandleV1;\n  readonly externalSource: LinkedObjectExternalSourceV1;\n  readonly candidateSnapshot: DocumentV1;\n};\n\nexport interface LinkedObjectRefreshWorkflowResultV1 {\n  readonly state: LinkedObjectRefreshWorkflowStateV1;\n  readonly stage: LinkedObjectRefreshStageV1;\n  readonly layer: LinkedObjectLayerV1;\n  readonly committed: boolean;\n  readonly handlePersisted: boolean;\n  readonly message: string | null;\n}\n\n"""
if controller.count(anchor) != 1:
    raise SystemExit('refresh commit result anchor mismatch')
controller = controller.replace(anchor, insert, 1)

helper_anchor = """function persistentHandleLinkResult(\n  layer: LinkedObjectLayerV1,\n  state: LinkedObjectPersistentHandleLinkStateV1,\n  handlePersisted: boolean,\n  sourceHash: string | null,\n  message: string | null,\n): LinkedObjectPersistentHandleLinkResultV1 {\n  return Object.freeze({ state, layer, handlePersisted, sourceHash, message });\n}\n\n"""
helper_insert = helper_anchor + """function refreshWorkflowResult(\n  state: LinkedObjectRefreshWorkflowStateV1,\n  stage: LinkedObjectRefreshStageV1,\n  layer: LinkedObjectLayerV1,\n  committed: boolean,\n  handlePersisted: boolean,\n  message: string | null,\n): LinkedObjectRefreshWorkflowResultV1 {\n  return Object.freeze({ state, stage, layer, committed, handlePersisted, message });\n}\n\n"""
if controller.count(helper_anchor) != 1:
    raise SystemExit('persistent handle result helper anchor mismatch')
controller = controller.replace(helper_anchor, helper_insert, 1)

method_anchor = """  async stageRelink(input: {\n    readonly layer: LinkedObjectLayerV1;\n    readonly handle: LinkedObjectExternalHandleV1;\n  }): Promise<LinkedObjectRefreshStageV1> {\n    return this.#stageFromHandle(input.layer, input.handle);\n  }\n\n"""
method_insert = """  async refresh(input: {\n    readonly projectId: ProjectId;\n    readonly layer: LinkedObjectLayerV1;\n    readonly review: (\n      stage: LinkedObjectReadyRefreshStageV1,\n    ) => LinkedObjectRefreshDecisionV1 | Promise<LinkedObjectRefreshDecisionV1>;\n    readonly getCurrentLayer: () =>\n      | LinkedObjectLayerV1\n      | null\n      | Promise<LinkedObjectLayerV1 | null>;\n    readonly commitTransaction: (nextLayer: LinkedObjectLayerV1) => Promise<void>;\n  }): Promise<LinkedObjectRefreshWorkflowResultV1> {\n    const stage = await this.stageRefresh({ projectId: input.projectId, layer: input.layer });\n    if (\n      stage.state !== 'ready' ||\n      stage.handle === null ||\n      stage.externalSource === null ||\n      stage.candidateSnapshot === null\n    ) {\n      const state: LinkedObjectRefreshWorkflowStateV1 =\n        stage.state === 'ready' ? 'invalid' : stage.state;\n      return refreshWorkflowResult(\n        state,\n        stage,\n        input.layer,\n        false,\n        false,\n        stage.state === 'ready' ? 'Refresh stage was incomplete and cannot be committed.' : stage.message,\n      );\n    }\n\n    const readyStage = stage as LinkedObjectReadyRefreshStageV1;\n    const decision = await input.review(readyStage);\n    if (decision !== 'commit') {\n      return refreshWorkflowResult(\n        'cancelled',\n        stage,\n        input.layer,\n        false,\n        false,\n        'External refresh was cancelled; embedded snapshot remains unchanged.',\n      );\n    }\n\n    const currentLayer = await input.getCurrentLayer();\n    if (\n      currentLayer === null ||\n      currentLayer.objectId !== stage.layer.objectId ||\n      currentLayer.revision !== stage.layer.revision\n    ) {\n      return refreshWorkflowResult(\n        'stale',\n        stage,\n        input.layer,\n        false,\n        false,\n        'Linked object changed while the refresh was being reviewed; stage again before committing.',\n      );\n    }\n\n    const result = await this.commit({\n      projectId: input.projectId,\n      stage,\n      commitTransaction: input.commitTransaction,\n    });\n    return refreshWorkflowResult(\n      'committed',\n      stage,\n      result.layer,\n      true,\n      result.handlePersisted,\n      result.handlePersisted\n        ? null\n        : 'Refresh committed, but the optional persistent external handle could not be retained.',\n    );\n  }\n\n""" + method_anchor
if controller.count(method_anchor) != 1:
    raise SystemExit('stageRelink method anchor mismatch')
controller = controller.replace(method_anchor, method_insert, 1)
controller_path.write_text(controller)

test_path = Path('tests/unit/linked-object-refresh-workflow.test.ts')
if test_path.exists():
    raise SystemExit('M9D-002 test file already exists')
test_path.write_text("""import { describe, expect, it } from 'vitest';\nimport type { DocumentV1 } from '../../src/domain/document.js';\nimport { createProjectId } from '../../src/domain/identity.js';\nimport { createLinkedObjectLayer, type LinkedObjectLayerV1 } from '../../src/domain/special-layers.js';\nimport {\n  LinkedObjectExternalControllerV1,\n  type LinkedObjectExternalFileV1,\n  type LinkedObjectExternalHandleStoreV1,\n  type LinkedObjectExternalHandleV1,\n} from '../../src/app/linked-object-external-controller.js';\n\nfunction documentFixture(marker: string): DocumentV1 {\n  return Object.freeze({ marker }) as unknown as DocumentV1;\n}\n\nfunction fileFixture(name: string, text: string): LinkedObjectExternalFileV1 {\n  const bytes = new TextEncoder().encode(text);\n  return Object.freeze({\n    name,\n    type: 'image/png',\n    size: bytes.byteLength,\n    lastModified: 1,\n    async arrayBuffer(): Promise<ArrayBuffer> {\n      return bytes.slice().buffer;\n    },\n  });\n}\n\nfunction handleFixture(file: LinkedObjectExternalFileV1): LinkedObjectExternalHandleV1 {\n  return Object.freeze({\n    kind: 'file',\n    name: file.name,\n    async getFile() {\n      return file;\n    },\n    async queryPermission() {\n      return 'granted' as const;\n    },\n  });\n}\n\nclass MemoryHandleStore implements LinkedObjectExternalHandleStoreV1 {\n  readonly handles = new Map<string, LinkedObjectExternalHandleV1>();\n\n  key(projectId: string, objectId: string): string {\n    return `${projectId}/${objectId}`;\n  }\n\n  async load(\n    projectId: Parameters<LinkedObjectExternalHandleStoreV1['load']>[0],\n    objectId: Parameters<LinkedObjectExternalHandleStoreV1['load']>[1],\n  ) {\n    return this.handles.get(this.key(projectId, objectId)) ?? null;\n  }\n\n  async save(\n    projectId: Parameters<LinkedObjectExternalHandleStoreV1['save']>[0],\n    objectId: Parameters<LinkedObjectExternalHandleStoreV1['save']>[1],\n    handle: LinkedObjectExternalHandleV1,\n  ) {\n    this.handles.set(this.key(projectId, objectId), handle);\n  }\n\n  async remove(\n    projectId: Parameters<LinkedObjectExternalHandleStoreV1['remove']>[0],\n    objectId: Parameters<LinkedObjectExternalHandleStoreV1['remove']>[1],\n  ) {\n    this.handles.delete(this.key(projectId, objectId));\n  }\n}\n\nasync function hashText(text: string): Promise<string> {\n  const bytes = new TextEncoder().encode(text);\n  const digest = await crypto.subtle.digest('SHA-256', bytes);\n  return [...new Uint8Array(digest)].map((byte) => byte.toString(16).padStart(2, '0')).join('');\n}\n\nfunction refreshFixture() {\n  const projectId = createProjectId();\n  const oldSnapshot = documentFixture('old');\n  const nextSnapshot = documentFixture('next');\n  const layer = createLinkedObjectLayer({\n    name: 'Linked',\n    embeddedSnapshot: oldSnapshot,\n    externalSource: {\n      originalName: 'source.png',\n      format: 'image/png',\n      sourceHash: '0'.repeat(64),\n    },\n  });\n  const store = new MemoryHandleStore();\n  const handle = handleFixture(fileFixture('source.png', 'changed source'));\n  store.handles.set(store.key(projectId, layer.objectId), handle);\n  const controller = new LinkedObjectExternalControllerV1({\n    store,\n    importer: {\n      async importExternal() {\n        return { embeddedSnapshot: nextSnapshot, incompatibilities: ['flattened-test'] };\n      },\n    },\n  });\n  return { projectId, oldSnapshot, nextSnapshot, layer, store, handle, controller };\n}\n\ndescribe('M9D-002 linked object refresh workflow', () => {\n  it('requires explicit review before one canonical transaction commits the staged refresh', async () => {\n    const fixture = refreshFixture();\n    let currentLayer: LinkedObjectLayerV1 | null = fixture.layer;\n    let reviews = 0;\n    let transactions = 0;\n\n    const result = await fixture.controller.refresh({\n      projectId: fixture.projectId,\n      layer: fixture.layer,\n      async review(stage) {\n        reviews += 1;\n        expect(stage.layer.embeddedSnapshot).toBe(fixture.oldSnapshot);\n        expect(stage.candidateSnapshot).toBe(fixture.nextSnapshot);\n        expect(stage.incompatibilities).toEqual(['flattened-test']);\n        expect(transactions).toBe(0);\n        return 'commit';\n      },\n      getCurrentLayer() {\n        return currentLayer;\n      },\n      async commitTransaction(nextLayer) {\n        transactions += 1;\n        currentLayer = nextLayer;\n      },\n    });\n\n    expect(reviews).toBe(1);\n    expect(transactions).toBe(1);\n    expect(result.state).toBe('committed');\n    expect(result.committed).toBe(true);\n    expect(result.layer.embeddedSnapshot).toBe(fixture.nextSnapshot);\n    expect(result.layer.revision).toBe(fixture.layer.revision + 1);\n    expect(fixture.layer.embeddedSnapshot).toBe(fixture.oldSnapshot);\n  });\n\n  it('cancels after review without mutating canonical content or creating history', async () => {\n    const fixture = refreshFixture();\n    let transactions = 0;\n\n    const result = await fixture.controller.refresh({\n      projectId: fixture.projectId,\n      layer: fixture.layer,\n      review() {\n        return 'cancel';\n      },\n      getCurrentLayer() {\n        throw new Error('cancelled refresh must not resolve current layer');\n      },\n      async commitTransaction() {\n        transactions += 1;\n      },\n    });\n\n    expect(result.state).toBe('cancelled');\n    expect(result.committed).toBe(false);\n    expect(transactions).toBe(0);\n    expect(result.layer).toBe(fixture.layer);\n    expect(result.layer.embeddedSnapshot).toBe(fixture.oldSnapshot);\n  });\n\n  it('rejects a stale reviewed stage instead of overwriting a newer linked-object revision', async () => {\n    const fixture = refreshFixture();\n    const newerLayer = Object.freeze({\n      ...fixture.layer,\n      revision: (fixture.layer.revision + 1) as typeof fixture.layer.revision,\n    });\n    let transactions = 0;\n\n    const result = await fixture.controller.refresh({\n      projectId: fixture.projectId,\n      layer: fixture.layer,\n      review() {\n        return 'commit';\n      },\n      getCurrentLayer() {\n        return newerLayer;\n      },\n      async commitTransaction() {\n        transactions += 1;\n      },\n    });\n\n    expect(result.state).toBe('stale');\n    expect(result.committed).toBe(false);\n    expect(transactions).toBe(0);\n    expect(result.layer.embeddedSnapshot).toBe(fixture.oldSnapshot);\n  });\n\n  it('short-circuits unchanged external content without review or a document transaction', async () => {\n    const projectId = createProjectId();\n    const snapshot = documentFixture('canonical');\n    const sourceHash = await hashText('same source');\n    const layer = createLinkedObjectLayer({\n      name: 'Linked',\n      embeddedSnapshot: snapshot,\n      externalSource: { originalName: 'source.png', format: 'image/png', sourceHash },\n    });\n    const store = new MemoryHandleStore();\n    store.handles.set(\n      store.key(projectId, layer.objectId),\n      handleFixture(fileFixture('source.png', 'same source')),\n    );\n    const controller = new LinkedObjectExternalControllerV1({\n      store,\n      importer: {\n        async importExternal() {\n          throw new Error('unchanged source must not be imported');\n        },\n      },\n    });\n\n    const result = await controller.refresh({\n      projectId,\n      layer,\n      review() {\n        throw new Error('unchanged source must not request review');\n      },\n      getCurrentLayer() {\n        throw new Error('unchanged source must not resolve current layer');\n      },\n      async commitTransaction() {\n        throw new Error('unchanged source must not create a transaction');\n      },\n    });\n\n    expect(result.state).toBe('unchanged');\n    expect(result.committed).toBe(false);\n    expect(result.layer).toBe(layer);\n    expect(result.layer.embeddedSnapshot).toBe(snapshot);\n  });\n});\n""")
